/*
 * Scroll animations for pages generated by nr_landingpage.
 *
 * Reads the animation map from every
 * <script type="application/json" data-nr-landingpage-animations> element:
 * an object that maps a content element UID to
 * {type, duration, delay, stagger}. The element #c<uid> is animated when it
 * scrolls into view. Nothing runs when the visitor prefers reduced motion,
 * and elements keep their normal appearance if this script does not load.
 *
 * No inline script and no eval: the file works under a Content Security
 * Policy that allows scripts from the site's own origin.
 */
(function () {
  'use strict';

  var START_STATES = {
    'fade-up': { opacity: '0', transform: 'translateY(40px)' },
    'fade-down': { opacity: '0', transform: 'translateY(-40px)' },
    'slide-left': { opacity: '0', transform: 'translateX(-60px)' },
    'slide-right': { opacity: '0', transform: 'translateX(60px)' },
    'zoom-in': { opacity: '0', transform: 'scale(0.8)' },
    'scale-up': { opacity: '0', transform: 'scale(0.5)' },
    'stagger-children': { opacity: '0', transform: 'translateY(20px)' }
  };

  function number(value, fallback, min, max) {
    var parsed = typeof value === 'number' ? value : parseFloat(value);
    if (!isFinite(parsed)) {
      return fallback;
    }
    return Math.min(max, Math.max(min, parsed));
  }

  function readAnimationMap() {
    var map = {};
    var blocks = document.querySelectorAll('script[type="application/json"][data-nr-landingpage-animations]');
    Array.prototype.forEach.call(blocks, function (block) {
      try {
        var data = JSON.parse(block.textContent || '{}');
        if (data && typeof data === 'object') {
          Object.keys(data).forEach(function (uid) {
            if (/^\d+$/.test(uid)) {
              map[uid] = data[uid];
            }
          });
        }
      } catch (e) {
        // An unreadable map leaves the page without animation.
      }
    });
    return map;
  }

  function hide(element, state) {
    element.style.opacity = state.opacity;
    element.style.transform = state.transform;
  }

  function reveal(element, duration, delay) {
    element.style.transition = 'opacity ' + duration + 's ease-out ' + delay + 's, transform ' + duration + 's ease-out ' + delay + 's';
    element.style.opacity = '';
    element.style.transform = '';
  }

  function typewriter(element, duration, delay) {
    var targets = element.querySelectorAll('h1, h2, p');
    Array.prototype.forEach.call(targets, function (target) {
      var text = target.textContent || '';
      if (text === '' || target.children.length > 0) {
        return;
      }
      target.textContent = '';
      var start = null;
      var step = function (time) {
        if (start === null) {
          start = time + delay * 1000;
        }
        var progress = Math.min(1, Math.max(0, (time - start) / (duration * 1000)));
        target.textContent = text.slice(0, Math.round(text.length * progress));
        if (progress < 1) {
          window.requestAnimationFrame(step);
        }
      };
      window.requestAnimationFrame(step);
    });
  }

  function parallax(element) {
    var update = function () {
      var rect = element.getBoundingClientRect();
      var viewport = window.innerHeight || document.documentElement.clientHeight;
      var progress = (viewport - rect.top) / (viewport + rect.height);
      progress = Math.min(1, Math.max(0, progress));
      element.style.transform = 'translateY(' + (-30 * progress).toFixed(1) + 'px)';
    };
    var scheduled = false;
    window.addEventListener('scroll', function () {
      if (!scheduled) {
        scheduled = true;
        window.requestAnimationFrame(function () {
          scheduled = false;
          update();
        });
      }
    }, { passive: true });
    update();
  }

  function prepare(element, config) {
    var type = String(config.type || '');
    var duration = number(config.duration, 0.8, 0.1, 3);
    var delay = number(config.delay, 0, 0, 2);
    var stagger = number(config.stagger, 0.15, 0.05, 0.5);

    if (type === 'parallax') {
      parallax(element);
      return null;
    }
    if (type === 'typewriter') {
      return function () { typewriter(element, duration, delay); };
    }
    var state = START_STATES[type];
    if (!state) {
      return null;
    }
    if (type === 'stagger-children') {
      var children = Array.prototype.slice.call(element.children);
      children.forEach(function (child) { hide(child, state); });
      return function () {
        children.forEach(function (child, index) { reveal(child, duration, delay + index * stagger); });
      };
    }
    hide(element, state);
    return function () { reveal(element, duration, delay); };
  }

  function start() {
    if (!('IntersectionObserver' in window)) {
      return;
    }
    if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      return;
    }
    var map = readAnimationMap();
    var pending = new Map();
    var observer = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting && pending.has(entry.target)) {
          var run = pending.get(entry.target);
          pending.delete(entry.target);
          observer.unobserve(entry.target);
          run();
        }
      });
    }, { threshold: 0.15 });

    Object.keys(map).forEach(function (uid) {
      var element = document.getElementById('c' + uid);
      var config = map[uid];
      if (!element || !config || typeof config !== 'object') {
        return;
      }
      var run = prepare(element, config);
      if (run) {
        pending.set(element, run);
        observer.observe(element);
      }
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', start);
  } else {
    start();
  }
})();
